using AutoPecasERP.Core.Entities; using AutoPecasERP.Core.Enums; using AutoPecasERP.Data.Context; using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Services.Auth;
public class AuthService { private readonly ErpDbContext _db; public AuthService(ErpDbContext db)=>_db=db; public async Task InicializarAsync(){await _db.Database.EnsureCreatedAsync(); await _db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS Fornecedores (Id INTEGER PRIMARY KEY AUTOINCREMENT, Empresa TEXT NOT NULL, Cnpj TEXT NULL, Contato TEXT NULL, Telefone TEXT NULL, Endereco TEXT NULL, Cidade TEXT NULL, Estado TEXT NULL, UltimaCompra TEXT NULL, Ativo INTEGER NOT NULL DEFAULT 1);"); await _db.Database.ExecuteSqlRawAsync("CREATE TABLE IF NOT EXISTS MovimentacoesEstoque (Id INTEGER PRIMARY KEY AUTOINCREMENT, ProdutoId INTEGER NOT NULL, Data TEXT NOT NULL, Tipo TEXT NOT NULL, Quantidade TEXT NOT NULL, SaldoAnterior TEXT NOT NULL, SaldoPosterior TEXT NOT NULL, Documento TEXT NULL, Observacao TEXT NULL, Usuario TEXT NULL, FOREIGN KEY(ProdutoId) REFERENCES Produtos(Id));"); if(!await _db.Usuarios.AnyAsync()){_db.Usuarios.Add(new Usuario{Nome="Administrador",Login="ADMIN",SenhaHash=BCrypt.Net.BCrypt.HashPassword("Admin@123"),Perfil=PerfilUsuario.Administrador});await _db.SaveChangesAsync();}} public async Task<Usuario?> LoginAsync(string login,string senha){var u=await _db.Usuarios.FirstOrDefaultAsync(x=>x.Login==login&&x.Ativo); if(u==null)return null;if(u.BloqueadoAte>DateTime.Now)return null;if(!BCrypt.Net.BCrypt.Verify(senha,u.SenhaHash)){u.TentativasFalhas++;if(u.TentativasFalhas>=5){u.BloqueadoAte=DateTime.Now.AddMinutes(15);u.TentativasFalhas=0;}await _db.SaveChangesAsync();return null;}u.TentativasFalhas=0;u.BloqueadoAte=null;await _db.SaveChangesAsync();return u;} }
